struct Item { value: int }
mut state := []
mut key := 0
while key < 64 { state = push(state, [0]) key += 1 }
export func snapshot() { return state }
export func edit(amount, limit) {
  mut j := 0
  while j < limit { state[j] = [amount] j += 1 }
  return amount
}

